{"file_path": "src/ai/dynamic-flow/step-handlers.ts", "initial_content": "/**
 * Step Handlers for Dynamic Flow Execution
 * 
 * Implements handlers for all step types:
 * - retrieve: RAG retrieval from vector store
 * - generate: LLM text generation
 * - tool: Tool execution
 * - format: Output formatting and transformation
 */

import { ai } from '@/ai/genkit';
import { FlowStep } from '@/lib/models/flow-config';
import { ContextManager } from './context-manager';
import { retrieveContext, RetrievalOptions } from '@/lib/rag/retrieval';
import { executeTool } from '@/services/tool-registry-service';

/**
 * Step execution result
 */
export interface StepExecutionResult {
  output: any;
  metadata?: {
    tokensUsed?: number;
    model?: string;
    duration?: number;
    sources?: Array<{
      content: string;
      score: number;
      sourceFile?: string;
      type: string;
    }>;
    [key: string]: any;
  };
}

/**
 * Execute a step based on its type
 */
export async function executeStep(
  step: FlowStep,
  input: Record<string, any>,
  context: ContextManager
): Promise<StepExecutionResult> {
  const startTime = Date.now();

  try {
    let result: StepExecutionResult;

    switch (step.type) {
      case 'retrieve':
        result = await executeRetrieveStep(step, input, context);
        break;

      case 'generate':
        result = await executeGenerateStep(step, input, context);
        break;

      case 'tool':
        result = await executeToolStep(step, input, context);
        break;

      case 'format':
        result = await executeFormatStep(step, input, context);
        break;

      default:
        throw new UnsupportedStepTypeError(step.type);
    }

    // Add execution duration to metadata
    const duration = Date.now() - startTime;
    result.metadata = {
      ...result.metadata,
      duration,
    };

    return result;
  } catch (error) {
    console.error(`Step execution failed: ${step.name}`, error);
    throw error;
  }
}

/**
 * Execute a RAG retrieval step
 * 
 * Retrieves relevant context from the vector store based on query
 */
export async function executeRetrieveStep(
  step: FlowStep,
  input: Record<string, any>,
  context: ContextManager
): Promise<StepExecutionResult> {
  try {
    const {
      query,
      topK = 5,
      minScore = 0.5,
      projectId,
      userId,
      includeTypes,
      useCache = true,
      rerank = false,
      rerankStrategy = 'hybrid',
      enhanced = false,
    } = input;

    if (!query) {
      throw new StepValidationError('retrieve', 'query parameter is required');
    }

    const options: RetrievalOptions = {
      topK,
      minScore,
      projectId,
      userId,
      includeTypes,
      useCache,
      rerank,
      rerankStrategy,
    };

    // Use enhanced retrieval if requested
    let result;
    if (enhanced) {
      const { retrieveContextEnhanced } = await import('@/lib/rag/retrieval');
      result = await retrieveContextEnhanced(query, options);
    } else {
      result = await retrieveContext(query, options);
    }

    return {
      output: {
        context: result.context,
        sources: result.sources,
        retrievedCount: result.sources.length,
      },
      metadata: {
        sources: result.sources,
        query,
        topK,
        minScore,
      },
    };
  } catch (error) {
    console.error('Retrieve step failed:', error);
    throw new StepExecutionError('retrieve', step.name, error);
  }
}

/**
 * Execute an LLM generation step
 * 
 * Generates text using the configured model and prompt
 */
export async function executeGenerateStep(
  step: FlowStep,
  input: Record<string, any>,
  context: ContextManager
): Promise<StepExecutionResult> {
  try {
    const {
      prompt,
      model = 'ollama/phi3:mini', // Default model
      systemPrompt,
      temperature = 0.7,
      maxTokens = 2000,
      topP = 0.9,
      topK = 40,
      stopSequences,
    } = input;

    if (!prompt) {
      throw new StepValidationError('generate', 'prompt parameter is required');
    }

    // Build the generation config
    const config: any = {
      temperature,
      maxOutputTokens: maxTokens,
      topP,
      topK,
    };

    if (stopSequences && stopSequences.length > 0) {
      config.stopSequences = stopSequences;
    }

    // Execute generation
    const response = await ai.generate({
      model,
      prompt: systemPrompt ? `${systemPrompt}\n\n${prompt}` : prompt,
      config,
    });

    // Extract text from response
    const generatedText = response.text();

    return {
      output: {
        text: generatedText,
        model,
      },
      metadata: {
        model,
        tokensUsed: response.usage?.totalTokens,
        temperature,
        maxTokens,
      },
    };
  } catch (error) {
    console.error('Generate step failed:', error);
    throw new StepExecutionError('generate', step.name, error);
  }
}

/**
 * Execute a tool step
 * 
 * Executes a registered tool with provided parameters
 */
export async function executeToolStep(
  step: FlowStep,
  input: Record<string, any>,
  context: ContextManager
): Promise<StepExecutionResult> {
  try {
    const {
      toolName,
      parameters = {},
      timeout,
    } = input;

    if (!toolName) {
      throw new StepValidationError('tool', 'toolName parameter is required');
    }

    // Execute the tool through the registry service
    const toolResult = await executeTool(toolName, parameters, timeout);

    return {
      output: {
        result: toolResult,
        toolName,
      },
      metadata: {
        toolName,
        parametersCount: Object.keys(parameters).length,
      },
    };
  } catch (error) {
    console.error('Tool step failed:', error);
    throw new StepExecutionError('tool', step.name, error);
  }
}

/**
 * Execute a format step
 * 
 * Formats and transforms data using templates and transformations
 */
export async function executeFormatStep(
  step: FlowStep,
  input: Record<string, any>,
  context: ContextManager
): Promise<StepExecutionResult> {
  try {
    const {
      template,
      format = 'text',
      data,
      transformation,
    } = input;

    if (!data) {
      throw new StepValidationError('format', 'data parameter is required');
    }

    let output: any;

    // Apply transformation if specified
    const transformedData = transformation 
      ? applyTransformation(data, transformation)
      : data;

    // Format based on type
    switch (format) {
      case 'json':
        output = formatAsJSON(transformedData);
        break;

      case 'markdown':
        output = formatAsMarkdown(transformedData, template);
        break;

      case 'text':
        output = formatAsText(transformedData, template);
        break;

      case 'html':
        output = formatAsHTML(transformedData, template);
        break;

      case 'csv':
        output = formatAsCSV(transformedData);
        break;

      default:
        throw new StepValidationError('format', `Unsupported format: ${format}`);
    }

    return {
      output: {
        formatted: output,
        format,
      },
      metadata: {
        format,
        hasTemplate: !!template,
        hasTransformation: !!transformation,
      },
    };
  } catch (error) {
    console.error('Format step failed:', error);
    throw new StepExecutionError('format', step.name, error);
  }
}

/**
 * Apply a transformation to data
 */
function applyTransformation(data: any, transformation: string): any {
  try {
    // Support simple transformations
    switch (transformation) {
      case 'uppercase':
        return typeof data === 'string' ? data.toUpperCase() : data;

      case 'lowercase':
        return typeof data === 'string' ? data.toLowerCase() : data;

      case 'trim':
        return typeof data === 'string' ? data.trim() : data;

      case 'stringify':
        return JSON.stringify(data, null, 2);

      case 'parse':
        return typeof data === 'string' ? JSON.parse(data) : data;

      case 'flatten':
        return Array.isArray(data) ? data.flat() : data;

      case 'compact':
        return Array.isArray(data) ? data.filter(Boolean) : data;

      default:
        // Try to execute as a JavaScript expression
        // Note: This is potentially dangerous and should be sandboxed in production
        console.warn('Custom transformation not sandboxed:', transformation);
        return data;
    }
  } catch (error) {
    console.error('Transformation failed:', error);
    return data;
  }
}

/**
 * Format data as JSON
 */
function formatAsJSON(data: any): string {
  return JSON.stringify(data, null, 2);
}

/**
 * Format data as Markdown
 */
function formatAsMarkdown(data: any, template?: string): string {
  if (template) {
    return interpolateTemplate(template, data);
  }

  // Default markdown formatting
  if (typeof data === 'string') {
    return data;
  }

  if (Array.isArray(data)) {
    return data.map((item, idx) => `${idx + 1}. ${formatAsMarkdown(item)}`).join('\n');
  }

  if (typeof data === 'object' && data !== null) {
    return Object.entries(data)
      .map(([key, value]) => `**${key}**: ${value}`)
      .join('\n\n');
  }

  return String(data);
}

/**
 * Format data as plain text
 */
function formatAsText(data: any, template?: string): string {
  if (template) {
    return interpolateTemplate(template, data);
  }

  // Default text formatting
  if (typeof data === 'string') {
    return data;
  }

  if (Array.isArray(data)) {
    return data.join('\n');
  }

  if (typeof data === 'object' && data !== null) {
    return Object.entries(data)
      .map(([key, value]) => `${key}: ${value}`)
      .join('\n');
  }

  return String(data);
}

/**
 * Format data as HTML
 */
function formatAsHTML(data: any, template?: string): string {
  if (template) {
    return interpolateTemplate(template, data);
  }

  // Default HTML formatting
  if (typeof data === 'string') {
    return `<p>${escapeHTML(data)}</p>`;
  }

  if (Array.isArray(data)) {
    const items = data.map(item => `<li>${escapeHTML(String(item))}</li>`).join('');
    return `<ul>${items}</ul>`;
  }

  if (typeof data === 'object' && data !== null) {
    const items = Object.entries(data)
      .map(([key, value]) => `<dt>${escapeHTML(key)}</dt><dd>${escapeHTML(String(value))}</dd>`)
      .join('');
    return `<dl>${items}</dl>`;
  }

  return `<p>${escapeHTML(String(data))}</p>`;
}

/**
 * Format data as CSV
 */
function formatAsCSV(data: any): string {
  if (!Array.isArray(data)) {
    throw new Error('CSV format requires array data');
  }

  if (data.length === 0) {
    return '';
  }

  // Assume array of objects
  if (typeof data[0] === 'object' && data[0] !== null) {
    const headers = Object.keys(data[0]);
    const headerRow = headers.map(escapeCSV).join(',');
    const dataRows = data.map(row =>
      headers.map(header => escapeCSV(String(row[header] ?? ''))).join(',')
    );
    return [headerRow, ...dataRows].join('\n');
  }

  // Array of primitives
  return data.map(item => escapeCSV(String(item))).join(',');
}

/**
 * Interpolate template with data
 */
function interpolateTemplate(template: string, data: any): string {
  return template.replace(/\{\{([^}]+)\}\}/g, (match, key) => {
    const trimmedKey = key.trim();
    const value = getNestedValue(data, trimmedKey);
    return value !== undefined ? String(value) : match;
  });
}

/**
 * Get nested value from object using dot notation
 */
function getNestedValue(obj: any, path: string): any {
  return path.split('.').reduce((current, key) => current?.[key], obj);
}

/**
 * Escape HTML special characters
 */
function escapeHTML(text: string): string {
  const map: Record<string, string> = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;',
  };
  return text.replace(/[&<>"']/g, char => map[char]);
}

/**
 * Escape CSV values
 */
function escapeCSV(value: string): string {
  if (value.includes(',') || value.includes('"') || value.includes('\n')) {
    return `"${value.replace(/"/g, '""')}"`;
  }
  return value;
}

/**
 * Custom error classes
 */
export class StepExecutionError extends Error {
  public readonly stepType: string;
  public readonly stepName: string;
  public readonly cause?: any;

  constructor(stepType: string, stepName: string, cause?: any) {
    const message = cause instanceof Error 
      ? `${stepType} step "${stepName}" failed: ${cause.message}`
      : `${stepType} step "${stepName}" failed`;
    super(message);
    this.name = 'StepExecutionError';
    this.stepType = stepType;
    this.stepName = stepName;
    this.cause = cause;
  }
}

export class StepValidationError extends Error {
  public readonly stepType: string;

  constructor(stepType: string, message: string) {
    super(`${stepType} step validation failed: ${message}`);
    this.name = 'StepValidationError';
    this.stepType = stepType;
  }
}

export class UnsupportedStepTypeError extends Error {
  constructor(stepType: string) {
    super(`Unsupported step type: ${stepType}`);
    this.name = 'UnsupportedStepTypeError';
  }
}

/**
 * Export all step handlers
 */
export const stepHandlers = {
  retrieve: executeRetrieveStep,
  generate: executeGenerateStep,
  tool: executeToolStep,
  format: executeFormatStep,
};
"}

{"file_path": "src/ai/tool-registry.ts", "initial_content": "/**
 * Tool Registry Integration Layer
 * 
 * Provides a unified interface for registering and accessing tools
 * across the dynamic flow system. Integrates built-in tools from
 * src/ai/tools with the database-backed tool registry service.
 */

import { toolRegistryService, registerBuiltinTool } from '@/services/tool-registry-service';
import { BuiltinToolMetadata } from '@/lib/models/tool-config';
import * as tools from '@/ai/tools';

/**
 * Initialize the tool registry with all built-in tools
 */
export async function initializeToolRegistry(): Promise<void> {
  console.log('Initializing tool registry...');

  // Register all built-in tools
  await registerBuiltinTools();

  console.log('Tool registry initialization complete');
}

/**
 * Register all built-in tools from src/ai/tools
 */
async function registerBuiltinTools(): Promise<void> {
  const registeredTools: string[] = [];

  // Grammar & Style Tools
  registerGrammarAndStyleTools(registeredTools);

  // Document Structure Tools
  registerDocumentStructureTools(registeredTools);

  // Citations & References Tools
  registerCitationsAndReferencesTools(registeredTools);

  // Comprehensive Analysis Tools
  registerComprehensiveAnalysisTools(registeredTools);

  // Project Analysis Tools
  registerProjectAnalysisTools(registeredTools);

  // Documentation Generation Tools
  registerDocumentationGenerationTools(registeredTools);

  // Reporting & Metrics Tools
  registerReportingAndMetricsTools(registeredTools);

  // Prompt Architect Tools
  registerPromptArchitectTools(registeredTools);

  // Search & Research Tools
  registerSearchAndResearchTools(registeredTools);

  console.log(`Registered ${registeredTools.length} built-in tools:`, registeredTools);
}

/**
 * Register Grammar & Style Tools
 */
function registerGrammarAndStyleTools(registered: string[]): void {
  // Check Grammar Tool
  if (tools.checkGrammarTool) {
    registerBuiltinTool({
      name: 'checkGrammar',
      displayName: 'Grammar Checker',
      description: 'Analyzes text for grammatical errors, spelling mistakes, and punctuation issues',
      category: 'grammar-style',
      handler: async (params: any) => tools.checkGrammarTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'Text to check for grammar errors' },
        },
        required: ['text'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          errors: { type: 'array', items: { type: 'object' } },
          score: { type: 'number' },
          suggestions: { type: 'array', items: { type: 'string' } },
        },
      },
      examples: [
        {
          name: 'Check basic grammar',
          input: { text: 'She go to the store yesterday.' },
          expectedOutput: {
            errors: [{ message: 'Subject-verb agreement error', position: 4 }],
            score: 0.7,
            suggestions: ['She went to the store yesterday.'],
          },
        },
      ],
    });
    registered.push('checkGrammar');
  }

  // Analyze Tone Tool
  if (tools.analyzeToneTool) {
    registerBuiltinTool({
      name: 'analyzeTone',
      displayName: 'Tone Analyzer',
      description: 'Analyzes the tone and sentiment of text',
      category: 'grammar-style',
      handler: async (params: any) => tools.analyzeToneTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'Text to analyze' },
        },
        required: ['text'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          tone: { type: 'string' },
          sentiment: { type: 'string' },
          confidence: { type: 'number' },
        },
      },
    });
    registered.push('analyzeTone');
  }

  // Check Readability Tool
  if (tools.checkReadabilityTool) {
    registerBuiltinTool({
      name: 'checkReadability',
      displayName: 'Readability Checker',
      description: 'Analyzes text readability and complexity',
      category: 'grammar-style',
      handler: async (params: any) => tools.checkReadabilityTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'Text to analyze' },
        },
        required: ['text'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          score: { type: 'number' },
          grade: { type: 'string' },
          suggestions: { type: 'array', items: { type: 'string' } },
        },
      },
    });
    registered.push('checkReadability');
  }

  // Improve Word Choice Tool
  if (tools.improveWordChoiceTool) {
    registerBuiltinTool({
      name: 'improveWordChoice',
      displayName: 'Word Choice Improver',
      description: 'Suggests better word choices for improved clarity and impact',
      category: 'grammar-style',
      handler: async (params: any) => tools.improveWordChoiceTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'Text to improve' },
        },
        required: ['text'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          suggestions: { type: 'array', items: { type: 'object' } },
        },
      },
    });
    registered.push('improveWordChoice');
  }
}

/**
 * Register Document Structure Tools
 */
function registerDocumentStructureTools(registered: string[]): void {
  if (tools.analyzeDocumentStructureTool) {
    registerBuiltinTool({
      name: 'analyzeDocumentStructure',
      displayName: 'Document Structure Analyzer',
      description: 'Analyzes the structure and organization of a document',
      category: 'document-structure',
      handler: async (params: any) => tools.analyzeDocumentStructureTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          document: { type: 'string', description: 'Document content to analyze' },
        },
        required: ['document'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          structure: { type: 'object' },
          issues: { type: 'array', items: { type: 'string' } },
        },
      },
    });
    registered.push('analyzeDocumentStructure');
  }

  if (tools.checkLogicalFlowTool) {
    registerBuiltinTool({
      name: 'checkLogicalFlow',
      displayName: 'Logical Flow Checker',
      description: 'Checks the logical flow and coherence of arguments',
      category: 'document-structure',
      handler: async (params: any) => tools.checkLogicalFlowTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'Text to analyze' },
        },
        required: ['text'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          score: { type: 'number' },
          issues: { type: 'array', items: { type: 'string' } },
        },
      },
    });
    registered.push('checkLogicalFlow');
  }

  if (tools.analyzeArgumentStructureTool) {
    registerBuiltinTool({
      name: 'analyzeArgumentStructure',
      displayName: 'Argument Structure Analyzer',
      description: 'Analyzes the structure and validity of arguments',
      category: 'document-structure',
      handler: async (params: any) => tools.analyzeArgumentStructureTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'Argument text to analyze' },
        },
        required: ['text'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          claims: { type: 'array', items: { type: 'string' } },
          evidence: { type: 'array', items: { type: 'string' } },
          strength: { type: 'number' },
        },
      },
    });
    registered.push('analyzeArgumentStructure');
  }
}

/**
 * Register Citations & References Tools
 */
function registerCitationsAndReferencesTools(registered: string[]): void {
  if (tools.validateCitationsTool) {
    registerBuiltinTool({
      name: 'validateCitations',
      displayName: 'Citation Validator',
      description: 'Validates citations for format and completeness',
      category: 'citations-references',
      handler: async (params: any) => tools.validateCitationsTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          citations: { type: 'array', items: { type: 'string' } },
          style: { type: 'string', enum: ['APA', 'MLA', 'Chicago', 'Harvard'] },
        },
        required: ['citations'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          valid: { type: 'boolean' },
          errors: { type: 'array', items: { type: 'object' } },
        },
      },
    });
    registered.push('validateCitations');
  }

  if (tools.checkReferencesTool) {
    registerBuiltinTool({
      name: 'checkReferences',
      displayName: 'Reference Checker',
      description: 'Checks references for completeness and accuracy',
      category: 'citations-references',
      handler: async (params: any) => tools.checkReferencesTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          references: { type: 'array', items: { type: 'string' } },
        },
        required: ['references'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          valid: { type: 'boolean' },
          issues: { type: 'array', items: { type: 'string' } },
        },
      },
    });
    registered.push('checkReferences');
  }

  if (tools.matchCitationsToReferencesTool) {
    registerBuiltinTool({
      name: 'matchCitationsToReferences',
      displayName: 'Citation-Reference Matcher',
      description: 'Matches in-text citations to reference list entries',
      category: 'citations-references',
      handler: async (params: any) => tools.matchCitationsToReferencesTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          citations: { type: 'array', items: { type: 'string' } },
          references: { type: 'array', items: { type: 'string' } },
        },
        required: ['citations', 'references'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          matched: { type: 'array', items: { type: 'object' } },
          unmatched: { type: 'array', items: { type: 'string' } },
        },
      },
    });
    registered.push('matchCitationsToReferences');
  }
}

/**
 * Register Comprehensive Analysis Tools
 */
function registerComprehensiveAnalysisTools(registered: string[]): void {
  if (tools.analyzeDocumentQualityTool) {
    registerBuiltinTool({
      name: 'analyzeDocumentQuality',
      displayName: 'Document Quality Analyzer',
      description: 'Performs comprehensive quality analysis of a document',
      category: 'analysis',
      handler: async (params: any) => tools.analyzeDocumentQualityTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          document: { type: 'string', description: 'Document to analyze' },
          criteria: { type: 'array', items: { type: 'string' } },
        },
        required: ['document'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          overallScore: { type: 'number' },
          scores: { type: 'object' },
          recommendations: { type: 'array', items: { type: 'string' } },
        },
      },
    });
    registered.push('analyzeDocumentQuality');
  }
}

/**
 * Register Project Analysis Tools
 */
function registerProjectAnalysisTools(registered: string[]): void {
  if (tools.analyzeProjectStructureTool) {
    registerBuiltinTool({
      name: 'analyzeProjectStructure',
      displayName: 'Project Structure Analyzer',
      description: 'Analyzes the structure and organization of a project',
      category: 'project-analysis',
      handler: async (params: any) => tools.analyzeProjectStructureTool.call(params),
      inputSchema: {
        type: 'object',
        properties: {
          projectPath: { type: 'string', description: 'Path to project' },
        },
        required: ['projectPath'],
      },
      outputSchema: {
        type: 'object',
        properties: {
          structure: { type: 'object' },
          metrics: { type: 'object' },
        },
      },
    });
    registered.push('analyzeProjectStructure');
  }

  if (tools.analyzeCodeComplexityTool) {
    registerBuiltinTool({
      name: 'analyzeCodeComplexity',
      displayName: 'Code Complexity Analyzer',
      description: 'Analyzes code complexity metrics',
      category: 'project-analysis',
