        expect(result.output.formatted).toBe('hello world');
      });

      it('should apply stringify transformation', async () => {
        const input = {
          data: { key: 'value' },
          format: 'text',
          transformation: 'stringify',
        };

        const result = await executeFormatStep(formatStep, input, context);

        expect(result.output.formatted).toContain('"key": "value"');
