      it('should apply flatten transformation', async () => {
        const input = {
          data: [[1, 2], [3, 4]],
          format: 'json',
          transformation: 'flatten',
        };

        const result = await executeFormatStep(formatStep, input, context);

        const parsed = JSON.parse(result.output.formatted);
        expect(parsed).toEqual([1, 2, 3, 4]);
      });
    });

    it('should throw validation error when data is missing', async () => {
      const input = {
        format: 'json',
