      await expect(
        executeFormatStep(formatStep, input, context)
      ).rejects.toThrow(StepValidationError);
    });

    it('should include metadata about formatting', async () => {
      const input = {
        data: 'test',
        format: 'text',
        template: 'Template: {{data}}',
        transformation: 'uppercase',
      };

      const result = await executeFormatStep(formatStep, input, context);

      expect(result.metadata?.format).toBe('text');
      expect(result.metadata?.hasTemplate).toBe(true);
      expect(result.metadata?.hasTransformation).toBe(true);
    });
  });
});
