### Flow Step

```typescript
interface FlowStep {
  id: string;
  name: string;
  type: 'retrieve' | 'generate' | 'tool' | 'format';
  handler: string;
  inputMapping: Record<string, string>;
  outputMapping: Record<string, string>;
  config?: Record<string, any>;
  retryPolicy?: RetryPolicy;
  timeout?: number;
}
