```typescript
interface ToolConfig {
  name: string;
  displayName: string;
  description: string;
  type: 'builtin' | 'custom' | 'external';
  category: string;
  status: 'active' | 'inactive';
  inputSchema: JSONSchema;
  outputSchema: JSONSchema;
