{"file_path": "src/lib/middleware/auth-middleware.ts", "initial_content": "/**
 * Authentication and Authorization Middleware
 * 
 * Provides authentication and role-based access control for API routes
 */

import { NextRequest, NextResponse } from 'next/server';
import { auth } from '@/lib/firebase/server-init';

/**
 * User roles for authorization
 */
export enum UserRole {
  ADMIN = 'admin',
  USER = 'user',
  VIEWER = 'viewer',
}

/**
 * Authenticated user information
 */
export interface AuthenticatedUser {
  uid: string;
  email: string | null;
  role: UserRole;
  displayName?: string;
}

/**
 * Extract and verify Firebase Auth token from request
 */
export async function extractAuthToken(request: NextRequest): Promise<string | null> {
  // Try to get token from Authorization header
  const authHeader = request.headers.get('authorization');

  if (authHeader?.startsWith('Bearer ')) {
    return authHeader.substring(7);
  }

  // Try to get token from cookie
  const cookieToken = request.cookies.get('auth-token')?.value;
  if (cookieToken) {
    return cookieToken;
  }

  return null;
}

/**
 * Verify authentication token and get user information
 */
export async function verifyAuthToken(token: string): Promise<AuthenticatedUser | null> {
  try {
    // Verify the Firebase ID token
    const decodedToken = await auth.verifyIdToken(token);

    // Get user role from custom claims or default to 'user'
    const role = (decodedToken.role as UserRole) || UserRole.USER;

    return {
      uid: decodedToken.uid,
      email: decodedToken.email || null,
      role,
      displayName: decodedToken.name,
    };
  } catch (error) {
    console.error('Token verification failed:', error);
    return null;
  }
}

/**
 * Authenticate request and return user information
 */
export async function authenticateRequest(
  request: NextRequest
): Promise<{ user: AuthenticatedUser | null; error?: string }> {
  const token = await extractAuthToken(request);

  if (!token) {
    return {
      user: null,
      error: 'Authentication token not provided',
    };
  }

  const user = await verifyAuthToken(token);

  if (!user) {
    return {
      user: null,
      error: 'Invalid or expired authentication token',
    };
  }

  return { user };
}

/**
 * Middleware function to require authentication
 */
export async function requireAuth(
  request: NextRequest
): Promise<{ user: AuthenticatedUser } | NextResponse> {
  const { user, error } = await authenticateRequest(request);

  if (!user) {
    return NextResponse.json(
      {
        success: false,
        error: error || 'Authentication required',
      },
      { status: 401 }
    );
  }

  return { user };
}

/**
 * Middleware function to require specific role(s)
 */
export async function requireRole(
  request: NextRequest,
  allowedRoles: UserRole[]
): Promise<{ user: AuthenticatedUser } | NextResponse> {
  const authResult = await requireAuth(request);

  // If authentication failed, return the error response
  if (authResult instanceof NextResponse) {
    return authResult;
  }

  const { user } = authResult;

  // Check if user has required role
  if (!allowedRoles.includes(user.role)) {
    return NextResponse.json(
      {
        success: false,
        error: 'Insufficient permissions',
        requiredRoles: allowedRoles,
        userRole: user.role,
      },
      { status: 403 }
    );
  }

  return { user };
}

/**
 * Middleware function to require admin role
 */
export async function requireAdmin(
  request: NextRequest
): Promise<{ user: AuthenticatedUser } | NextResponse> {
  return requireRole(request, [UserRole.ADMIN]);
}

/**
 * Check if user owns a resource
 */
export function checkResourceOwnership(
  user: AuthenticatedUser,
  resourceUserId: string
): boolean {
  // Admins can access any resource
  if (user.role === UserRole.ADMIN) {
    return true;
  }

  // Users can only access their own resources
  return user.uid === resourceUserId;
}

/**
 * Middleware to require resource ownership or admin role
 */
export async function requireOwnershipOrAdmin(
  request: NextRequest,
  resourceUserId: string
): Promise<{ user: AuthenticatedUser } | NextResponse> {
  const authResult = await requireAuth(request);

  if (authResult instanceof NextResponse) {
    return authResult;
  }

  const { user } = authResult;

  if (!checkResourceOwnership(user, resourceUserId)) {
    return NextResponse.json(
      {
        success: false,
        error: 'You do not have permission to access this resource',
      },
      { status: 403 }
    );
  }

  return { user };
}

/**
 * Set user role custom claim (admin only)
 */
export async function setUserRole(
  uid: string,
  role: UserRole
): Promise<void> {
  try {
    await auth.setCustomUserClaims(uid, { role });
  } catch (error) {
    console.error('Failed to set user role:', error);
    throw new Error('Failed to set user role');
  }
}

/**
 * Get user by UID
 */
export async function getUserByUid(uid: string) {
  try {
    return await auth.getUser(uid);
  } catch (error) {
    console.error('Failed to get user:', error);
    return null;
  }
}

/**
 * Rate limiting helper (simple in-memory implementation)
 * TODO: Replace with Redis-based implementation for production
 */
const rateLimitMap = new Map<string, { count: number; resetTime: number }>();

export function checkRateLimit(
  identifier: string,
  maxRequests: number = 100,
  windowMs: number = 60000 // 1 minute
): boolean {
  const now = Date.now();
  const record = rateLimitMap.get(identifier);

  if (!record || now > record.resetTime) {
    // Reset or create new record
    rateLimitMap.set(identifier, {
      count: 1,
      resetTime: now + windowMs,
    });
    return true;
  }

  if (record.count >= maxRequests) {
    return false; // Rate limit exceeded
  }

  record.count++;
  return true;
}

/**
 * Middleware to apply rate limiting
 */
export async function requireRateLimit(
  request: NextRequest,
  maxRequests: number = 100,
  windowMs: number = 60000
): Promise<true | NextResponse> {
  // Get identifier (IP address or user ID)
  const forwarded = request.headers.get('x-forwarded-for');
  const ip = forwarded ? forwarded.split(',')[0] : 'unknown';

  const { user } = await authenticateRequest(request);
  const identifier = user?.uid || ip;

  if (!checkRateLimit(identifier, maxRequests, windowMs)) {
    return NextResponse.json(
      {
        success: false,
        error: 'Rate limit exceeded',
        message: `Maximum ${maxRequests} requests per ${windowMs / 1000} seconds`,
      },
      { 
        status: 429,
        headers: {
          'Retry-After': String(Math.ceil(windowMs / 1000)),
        },
      }
    );
  }

  return true;
}

/**
 * Helper function to create protected API handler
 * 
 * Usage:
 * export const GET = withAuth(async (request, { user }) => {
 *   // Your handler code with authenticated user
 * });
 */
export function withAuth<T = any>(
  handler: (
    request: NextRequest,
    context: { user: AuthenticatedUser; params?: T }
  ) => Promise<NextResponse>
) {
  return async (request: NextRequest, context?: { params?: T }) => {
    const authResult = await requireAuth(request);

    if (authResult instanceof NextResponse) {
      return authResult;
    }

    return handler(request, { user: authResult.user, params: context?.params });
  };
}

/**
 * Helper function to create admin-only API handler
 */
export function withAdmin<T = any>(
  handler: (
    request: NextRequest,
    context: { user: AuthenticatedUser; params?: T }
  ) => Promise<NextResponse>
) {
  return async (request: NextRequest, context?: { params?: T }) => {
    const authResult = await requireAdmin(request);

    if (authResult instanceof NextResponse) {
      return authResult;
    }

    return handler(request, { user: authResult.user, params: context?.params });
  };
}

/**
 * Helper function to create role-based API handler
 */
export function withRole<T = any>(
  allowedRoles: UserRole[],
  handler: (
    request: NextRequest,
    context: { user: AuthenticatedUser; params?: T }
  ) => Promise<NextResponse>
) {
  return async (request: NextRequest, context?: { params?: T }) => {
    const authResult = await requireRole(request, allowedRoles);

    if (authResult instanceof NextResponse) {
      return authResult;
    }

    return handler(request, { user: authResult.user, params: context?.params });
  };
}

/**
 * Export authentication utilities
 */
export const authMiddleware = {
  requireAuth,
  requireAdmin,
  requireRole,
  requireOwnershipOrAdmin,
  requireRateLimit,
  authenticateRequest,
  extractAuthToken,
  verifyAuthToken,
  checkResourceOwnership,
  setUserRole,
  getUserByUid,
  withAuth,
  withAdmin,
  withRole,
};

export default authMiddleware;
"}

{"file_path": "src/app/api/__tests__/flows.integration.test.ts", "initial_content": "/**
 * Integration Tests for Flow Management APIs
 */

import { NextRequest } from 'next/server';
import { GET as listFlows, POST as createFlow } from '../admin/flows/route';
import { 
  GET as getFlow, 
  PUT as updateFlow, 
  DELETE as deleteFlow 
} from '../admin/flows/[flowId]/route';

// Mock Firebase and services
jest.mock('@/lib/firebase/server-init');
jest.mock('@/services/flow-config-service');

describe('Flow Management API', () => {
  let createdFlowId: string;

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('POST /api/admin/flows', () => {
    it('should create a new flow', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      const mockFlow = {
        id: 'flow_test123',
        name: 'test-flow',
        displayName: 'Test Flow',
        version: 1,
        status: 'draft',
        steps: [],
      };

      flowConfigService.createFlow.mockResolvedValue(mockFlow);

      const request = new NextRequest('http://localhost:3000/api/admin/flows', {
        method: 'POST',
        body: JSON.stringify({
          name: 'test-flow',
          displayName: 'Test Flow',
          description: 'Test flow description',
          steps: [
            {
              id: 'step1',
              name: 'Test Step',
              type: 'format',
              handler: 'format',
              inputMapping: {},
              outputMapping: {},
            },
          ],
        }),
      });

      const response = await createFlow(request);
      const data = await response.json();

      expect(response.status).toBe(201);
      expect(data.success).toBe(true);
      expect(data.flow).toBeDefined();
      expect(data.flow.id).toBe('flow_test123');
      expect(flowConfigService.createFlow).toHaveBeenCalled();
    });

    it('should return 400 for invalid flow data', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      const validationError = new Error('Validation failed');
      validationError.name = 'ValidationError';
      flowConfigService.createFlow.mockRejectedValue(validationError);

      const request = new NextRequest('http://localhost:3000/api/admin/flows', {
        method: 'POST',
        body: JSON.stringify({
          name: '', // Invalid: empty name
        }),
      });

      const response = await createFlow(request);
      const data = await response.json();

      expect(response.status).toBe(400);
      expect(data.success).toBe(false);
      expect(data.error).toBeDefined();
    });
  });

  describe('GET /api/admin/flows', () => {
    it('should list all flows', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      const mockFlows = [
        { id: 'flow1', name: 'flow-1', status: 'active' },
        { id: 'flow2', name: 'flow-2', status: 'draft' },
      ];

      flowConfigService.listFlows.mockResolvedValue(mockFlows);

      const request = new NextRequest('http://localhost:3000/api/admin/flows');

      const response = await listFlows(request);
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data.success).toBe(true);
      expect(data.flows).toHaveLength(2);
      expect(data.total).toBe(2);
    });

    it('should filter flows by status', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      const mockFlows = [
        { id: 'flow1', name: 'flow-1', status: 'active' },
      ];

      flowConfigService.listFlows.mockResolvedValue(mockFlows);

      const request = new NextRequest('http://localhost:3000/api/admin/flows?status=active');

      const response = await listFlows(request);
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data.flows).toHaveLength(1);
      expect(flowConfigService.listFlows).toHaveBeenCalledWith(
        expect.objectContaining({ status: 'active' })
      );
    });
  });

  describe('GET /api/admin/flows/{flowId}', () => {
    it('should get flow by ID', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      const mockFlow = {
        id: 'flow_test123',
        name: 'test-flow',
        displayName: 'Test Flow',
      };

      flowConfigService.getFlowById.mockResolvedValue(mockFlow);

      const request = new NextRequest('http://localhost:3000/api/admin/flows/flow_test123');

      const response = await getFlow(request, { params: { flowId: 'flow_test123' } });
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data.success).toBe(true);
      expect(data.flow.id).toBe('flow_test123');
    });

    it('should return 404 for non-existent flow', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      flowConfigService.getFlowById.mockResolvedValue(null);

      const request = new NextRequest('http://localhost:3000/api/admin/flows/nonexistent');

      const response = await getFlow(request, { params: { flowId: 'nonexistent' } });
      const data = await response.json();

      expect(response.status).toBe(404);
      expect(data.success).toBe(false);
      expect(data.error).toBe('Flow not found');
    });
  });

  describe('PUT /api/admin/flows/{flowId}', () => {
    it('should update flow', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      const mockUpdatedFlow = {
        id: 'flow_test123',
        name: 'test-flow',
        displayName: 'Updated Test Flow',
        version: 2,
      };

      flowConfigService.updateFlow.mockResolvedValue(mockUpdatedFlow);

      const request = new NextRequest('http://localhost:3000/api/admin/flows/flow_test123', {
        method: 'PUT',
        body: JSON.stringify({
          displayName: 'Updated Test Flow',
          versionMessage: 'Updated via test',
        }),
      });

      const response = await updateFlow(request, { params: { flowId: 'flow_test123' } });
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data.success).toBe(true);
      expect(data.flow.version).toBe(2);
    });

    it('should return 404 for updating non-existent flow', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      const notFoundError = new Error('Flow not found');
      notFoundError.name = 'FlowNotFoundError';
      flowConfigService.updateFlow.mockRejectedValue(notFoundError);

      const request = new NextRequest('http://localhost:3000/api/admin/flows/nonexistent', {
        method: 'PUT',
        body: JSON.stringify({ displayName: 'Updated' }),
      });

      const response = await updateFlow(request, { params: { flowId: 'nonexistent' } });
      const data = await response.json();

      expect(response.status).toBe(404);
      expect(data.success).toBe(false);
    });
  });

  describe('DELETE /api/admin/flows/{flowId}', () => {
    it('should delete flow', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      flowConfigService.deleteFlow.mockResolvedValue(undefined);

      const request = new NextRequest('http://localhost:3000/api/admin/flows/flow_test123', {
        method: 'DELETE',
      });

      const response = await deleteFlow(request, { params: { flowId: 'flow_test123' } });
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data.success).toBe(true);
      expect(data.message).toBe('Flow deleted successfully');
    });

    it('should return 404 for deleting non-existent flow', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');

      const notFoundError = new Error('Flow not found');
      notFoundError.name = 'FlowNotFoundError';
      flowConfigService.deleteFlow.mockRejectedValue(notFoundError);

      const request = new NextRequest('http://localhost:3000/api/admin/flows/nonexistent', {
        method: 'DELETE',
      });

      const response = await deleteFlow(request, { params: { flowId: 'nonexistent' } });
      const data = await response.json();

      expect(response.status).toBe(404);
      expect(data.success).toBe(false);
    });
  });
});
"}

{"file_path": "src/app/api/__tests__/execution.integration.test.ts", "initial_content": "/**
 * Integration Tests for Flow Execution APIs
 */

import { NextRequest } from 'next/server';
import { POST as executeFlow } from '../flows/execute/route';
import { POST as testFlow } from '../flows/test/route';

// Mock dependencies
jest.mock('@/ai/flows/dynamic-flow-executor');
jest.mock('@/services/flow-config-service');

describe('Flow Execution API', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('POST /api/flows/execute', () => {
    it('should execute a flow successfully', async () => {
      const { dynamicFlowExecutor } = require('@/ai/flows/dynamic-flow-executor');

      const mockResult = {
        success: true,
        executionId: 'exec_test123',
        traceId: 'trace_test123',
        output: {
          result: 'Execution result',
        },
        steps: [
          {
            stepId: 'step1',
            name: 'Test Step',
            status: 'completed',
            duration: 100,
          },
        ],
      };

      dynamicFlowExecutor.mockResolvedValue(mockResult);

      const request = new NextRequest('http://localhost:3000/api/flows/execute', {
        method: 'POST',
        body: JSON.stringify({
          flowName: 'test-flow',
          payload: {
            query: 'Test query',
          },
          userId: 'test-user',
          enableTracing: true,
        }),
      });

      const response = await executeFlow(request);
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data.success).toBe(true);
      expect(data.executionId).toBe('exec_test123');
      expect(data.traceId).toBe('trace_test123');
      expect(dynamicFlowExecutor).toHaveBeenCalledWith({
        flowName: 'test-flow',
        payload: { query: 'Test query' },
        userId: 'test-user',
        requestId: expect.any(String),
        enableTracing: true,
      });
    });

    it('should return 400 when flowName is missing', async () => {
      const request = new NextRequest('http://localhost:3000/api/flows/execute', {
        method: 'POST',
        body: JSON.stringify({
          payload: { query: 'Test' },
        }),
      });

      const response = await executeFlow(request);
      const data = await response.json();

      expect(response.status).toBe(400);
      expect(data.success).toBe(false);
      expect(data.error).toBe('Flow name is required');
    });

    it('should return 400 when payload is missing', async () => {
      const request = new NextRequest('http://localhost:3000/api/flows/execute', {
        method: 'POST',
        body: JSON.stringify({
          flowName: 'test-flow',
        }),
      });

      const response = await executeFlow(request);
      const data = await response.json();

      expect(response.status).toBe(400);
      expect(data.success).toBe(false);
      expect(data.error).toBe('Payload object is required');
    });

    it('should handle execution errors', async () => {
      const { dynamicFlowExecutor } = require('@/ai/flows/dynamic-flow-executor');

      dynamicFlowExecutor.mockRejectedValue(new Error('Execution failed'));

      const request = new NextRequest('http://localhost:3000/api/flows/execute', {
        method: 'POST',
        body: JSON.stringify({
          flowName: 'test-flow',
          payload: { query: 'Test' },
        }),
      });

      const response = await executeFlow(request);
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data.success).toBe(false);
      expect(data.error).toContain('Execution failed');
    });
  });

  describe('POST /api/flows/test', () => {
    it('should test a flow configuration', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');
      const { dynamicFlowExecutor } = require('@/ai/flows/dynamic-flow-executor');

      const mockTempFlow = {
        id: 'flow_temp123',
        name: 'test_temp_flow',
      };

      const mockResult = {
        success: true,
        output: { result: 'Test result' },
      };

      flowConfigService.createFlow.mockResolvedValue(mockTempFlow);
      flowConfigService.deleteFlow.mockResolvedValue(undefined);
      flowConfigService.listFlows.mockResolvedValue([]);
      dynamicFlowExecutor.mockResolvedValue(mockResult);

      const request = new NextRequest('http://localhost:3000/api/flows/test', {
        method: 'POST',
        body: JSON.stringify({
          flowConfig: {
            name: 'temp-test-flow',
            displayName: 'Temp Test Flow',
            steps: [
              {
                id: 'step1',
                name: 'Format Step',
                type: 'format',
                handler: 'format',
                inputMapping: {},
                outputMapping: {},
              },
            ],
          },
          payload: {
            text: 'test input',
          },
        }),
      });

      const response = await testFlow(request);
      const data = await response.json();

      expect(response.status).toBe(200);
      expect(data.success).toBe(true);
      expect(data.result).toBeDefined();
      expect(flowConfigService.createFlow).toHaveBeenCalled();
      expect(dynamicFlowExecutor).toHaveBeenCalled();
      expect(flowConfigService.deleteFlow).toHaveBeenCalledWith(mockTempFlow.id);
    });

    it('should return 400 when flowConfig is missing', async () => {
      const request = new NextRequest('http://localhost:3000/api/flows/test', {
        method: 'POST',
        body: JSON.stringify({
          payload: { test: 'data' },
        }),
      });

      const response = await testFlow(request);
      const data = await response.json();

      expect(response.status).toBe(400);
      expect(data.success).toBe(false);
      expect(data.error).toBe('Flow configuration is required');
    });

    it('should cleanup temporary flow on error', async () => {
      const { flowConfigService } = require('@/services/flow-config-service');
      const { dynamicFlowExecutor } = require('@/ai/flows/dynamic-flow-executor');

      const mockTempFlow = {
        id: 'flow_temp123',
        name: 'test_temp_flow',
      };

      flowConfigService.createFlow.mockResolvedValue(mockTempFlow);
      flowConfigService.listFlows.mockResolvedValue([mockTempFlow]);
      flowConfigService.deleteFlow.mockResolvedValue(undefined);
      dynamicFlowExecutor.mockRejectedValue(new Error('Test execution failed'));

      const request = new NextRequest('http://localhost:3000/api/flows/test', {
        method: 'POST',
        body: JSON.stringify({
          flowConfig: {
            name: 'temp-test-flow',
            steps: [],
          },
          payload: { test: 'data' },
        }),
      });

      const response = await testFlow(request);
      const data = await response.json();

      expect(response.status).toBe(500);
      expect(data.success).toBe(false);
      // Verify cleanup was attempted
      expect(flowConfigService.listFlows).toHaveBeenCalled();
    });
  });
});
"}

